// Added by Yuvraj Sahu on 16-2-2023
// Reason - to login restaurant

import React, { useState, useEffect } from "react";
import {
  View,
  Text,
  StyleSheet,
  Button,
  TextInput,
  ScrollView,
  TouchableOpacity,
  Alert,
  Pressable,
} from "react-native";

// import { userLogin } from "../api/ServiceApi";
import { Formik } from "formik";
// import { loginSchema } from "../validation/ValidationSchema";
import * as SecureStore from "expo-secure-store";
import Ionicons from "@expo/vector-icons/Ionicons";
import { restaurentAuthentication } from "../api/Services";
// import { useDispatch } from "react-redux";
// import { authLogin } from "../redux/slice/AuthSlice";

export default function LoginScreen() {
  const [showPassword, setShowPassword] = useState(false);
  // const dispatch = useDispatch();

  // const alertHandler = (msg) => {
  //   Alert.alert("Login", `${msg}`, [{ text: "OK", onPress: () => null }]);
  // };

  //when user click login button this method is called and handle user login  #mohendra sahu
  const submitLog = (values, { resetForm }) => {
    console.log("values: " + JSON.stringify(values));

    // restaurentAuthentication(values)
    //   .then(async (res) => {
    //     if (res.data.success && res.data.token) {
    //       await SecureStore.setItemAsync(
    //         "token",
    //         JSON.stringify(res.data.token)
    //       );
    //       await SecureStore.setItemAsync(
    //         "userData",
    //         JSON.stringify(res.data.userData[0])
    //       );

    //       dispatch(
    //         authLogin({ token: res.data.token, userData: res.data.userData[0] })
    //       );
    //       resetForm({ values: "" });
    //     } else {
    //       alertHandler(res.data.msg);
    //     }
    //   })
    //   .catch((err) => {
    //     alertHandler("Something went wrong! Please try again later.");
    //   });
  };

  return (
    <Formik
      initialValues={{ email: "", password: "" }}
      validateOnMount={true}
      // validationSchema={loginSchema}
      onSubmit={submitLog}
    >
      {({
        handleChange,
        handleBlur,
        handleSubmit,
        values,
        touched,
        isValid,
        errors,
      }) => (
        <ScrollView style={styles.container}>
          <View style={styles.container}>
            <View style={{ marginTop: 30 }}>
              <View>
                <Text style={styles.labels}>
                  <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
                  Email
                </Text>

                <TextInput
                  style={styles.input}
                  onChangeText={handleChange("email")}
                  onBlur={handleBlur("email")}
                  value={values.email}
                  placeholderTextColor="#A4A4A4"
                  placeholder="Enter your email"
                  keyboardType="email-address"
                  autoCapitalize="none"
                  autoCorrect={false}
                />
                {errors.email && touched.email && (
                  <Text style={styles.textdanger}>{errors.email}</Text>
                )}
              </View>

              <View>
                <Text style={styles.labels}>
                  <Text style={{ color: "red", fontWeight: "650" }}>* </Text>
                  Password
                </Text>

                <View style={styles.passContainer}>
                  <TextInput
                    style={styles.inputPassword}
                    onChangeText={handleChange("password")}
                    onBlur={handleBlur("password")}
                    value={values.password}
                    placeholderTextColor="#A4A4A4"
                    placeholder="Enter your password"
                    autoCapitalize="none"
                    autoCorrect={false}
                    secureTextEntry={!showPassword}
                  />

                  <TouchableOpacity
                    onPress={() => setShowPassword(!showPassword)}
                  >
                    <Ionicons
                      name={showPassword ? "eye" : "eye-off"}
                      size={24}
                      color="black"
                      style={styles.passIcon}
                    />
                  </TouchableOpacity>
                </View>

                {errors.password && touched.password && (
                  <Text style={styles.textdanger}>{errors.password}</Text>
                )}
              </View>
              <View
                style={{
                  marginBottom: 30,
                  marginHorizontal: 10,
                  marginTop: 10,
                }}
              >
                <Pressable
                  onPress={handleSubmit(submitLog)}
                  // disabled={!isValid}
                  style={{
                    backgroundColor: isValid ? "#6823cf" : "#E0E0E0",
                    height: 40,
                    alignItems: "center",
                    justifyContent: "center",
                    borderRadius: 3,
                  }}
                >
                  <Text
                    style={{
                      color: isValid ? "white" : "#989898",
                      fontSize: 16,
                      fontWeight: "bold",
                    }}
                  >
                    Login
                  </Text>
                </Pressable>
              </View>
            </View>
          </View>
        </ScrollView>
      )}
    </Formik>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    height: "100%",
    paddingHorizontal: 10,
    backgroundColor: "#fff",
  },
  mainHeader: {
    marginTop: "10%",
    fontSize: 20,
    fontWeight: "bold",
    textAlign: "center",
  },
  input: {
    height: 40,
    margin: 12,
    borderWidth: 1,
    padding: 10,
    marginTop: 10,
    fontSize: 16,
    borderRadius: 3,
  },
  passContainer: {
    flexDirection: "row",
    height: 40,
    borderWidth: 1,
    margin: 12,
    marginTop: 10,
    borderRadius: 3,
  },
  inputPassword: {
    paddingTop: 10,
    paddingLeft: 8,
    paddingBottom: 10,
    paddingRight: 10,
    fontSize: 15,
    borderRadius: 3,
    flex: 1,
  },
  passIcon: {
    margin: 5,
  },
  labels: {
    paddingHorizontal: 10,
  },
  textdanger: {
    color: "#dc3545",
    marginBottom: 10,
    paddingHorizontal: 10,
  },
});
